function norm(s){return String(s).toLowerCase().replace(/section|sec\.?|u\/s|s\./g,'').replace(/[^0-9a-z()]/g,'')}
function find(q){var k=norm(q);if(!k)return[];var ex=[],pre=[];ROWS.forEach(function(r){var o=norm(r[0]);if(o===k)ex.push(r);else if(o.indexOf(k+'(')===0)pre.push(r)});return ex.length?ex.concat(pre.slice(0,12)):pre.slice(0,30)}
window.SECFIND={find:find,norm:norm,ROWS:ROWS};
var f=$('#sf-form');if(!f)return;var q=$('#sf-q'),res=$('#sf-res');
var ST={c:'Checked against the Act: the new section is about the same subject.',n:'The section exists in the Act but its wording differs from the old heading: this match rests on the department\'s navigator alone.',m:'The number is not a section of the Act: do not rely on it.',s:'A Schedule table row as listed by the navigator (not checked row by row).',x:'As marked by the navigator.'};
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function ui(){var v=q.value.trim();if(!v){res.innerHTML='';return}var h=find(v);if(!h.length){res.innerHTML='<div class="sf-hit"><h3>No row found for "'+esc(v)+'"</h3><p>Type the section of the Income-tax Act, 1961 as a number with its letters, for example 80C, 44AD, 194C, 10(14) or 139(1). If the section is not listed, it may be among the rows <a href="/sections/not-matched/">that could not be read or matched</a>.</p></div>';return}
 res.innerHTML=h.map(function(r){return '<div class="sf-hit"><h3>Old section '+esc(r[0])+' <small>'+esc(r[1])+'</small></h3><p><b>Now:</b> '+esc(r[2])+'</p><p class="sf-warn">'+ST[r[3]]+'</p></div>'}).join('')}
f.addEventListener('submit',function(e){e.preventDefault();ui()});q.addEventListener('input',ui);
var m=location.hash.match(/q=([^&]+)/);if(m){q.value=decodeURIComponent(m[1]);ui()}
